"use client"

import * as React from "react"
import { Settings2Icon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { cn } from "@/lib/utils"

import planArt from "./images/plan-art.webp"
import { SettingsModal } from "./settings-modal"

function assetSrc(asset: string | { src: string }) {
  return typeof asset === "string" ? asset : asset.src
}

/**
 * Account settings modal — multi-page shell (General / Profile / Tools /
 * Storage) with an animated WebGL plan card on General.
 */
export default function AccountSettings({
  className,
  ...props
}: React.ComponentProps<"main">) {
  const [open, setOpen] = React.useState(false)

  return (
    <main
      className={cn(
        "flex w-full min-w-0 flex-col items-center justify-center bg-canvas px-4 py-8 text-foreground sm:px-6",
        className
      )}
      {...props}
    >
      <Button type="button" onClick={() => setOpen(true)} className="gap-2">
        <Settings2Icon className="size-4" />
        Open settings
      </Button>

      <SettingsModal
        open={open}
        onOpenChange={setOpen}
        defaultPage="general"
        planArtSrc={assetSrc(planArt)}
      />
    </main>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Current-plan artwork rendered through a WebGL fragment shader as a
 * wind-torn burning flag (wave + burn rim + sparks). Falls back to soft
 * token blobs when WebGL is unavailable.
 */

const VERT = /* glsl */ `
attribute vec2 a_pos;
varying vec2 v_uv;
void main() {
  v_uv = a_pos * 0.5 + 0.5;
  gl_Position = vec4(a_pos, 0.0, 1.0);
}
`

const FRAG = /* glsl */ `
precision mediump float;
uniform sampler2D u_tex;
uniform float u_time;
uniform vec2 u_mouse;
uniform float u_mouseStr;
varying vec2 v_uv;

float hash(vec2 p) {
  return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(
    mix(hash(i), hash(i + vec2(1.0, 0.0)), u.x),
    mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), u.x),
    u.y
  );
}

float fbm(vec2 p) {
  float v = 0.0;
  float a = 0.5;
  for (int i = 0; i < 4; i++) {
    v += a * noise(p);
    p = p * 2.03 + vec2(17.0, 9.2);
    a *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = v_uv;
  float edge = clamp(distance(uv, vec2(0.5)) * 1.6, 0.0, 1.0);
  float mouseBoost = u_mouseStr * smoothstep(0.2, 0.02, distance(v_uv, u_mouse));

  float amp = 0.004 + 0.022 * edge * edge + 0.012 * mouseBoost;
  uv.x += sin(uv.y * 9.0 + u_time * 2.2) * amp;
  uv.y += sin(uv.x * 12.0 - u_time * 2.7) * amp * 0.85;
  uv += (vec2(
    fbm(v_uv * 3.0 + vec2(u_time * 0.35, 0.0)),
    fbm(v_uv * 3.0 + vec2(0.0, u_time * 0.31) + 31.7)
  ) - 0.5) * 0.03 * edge;

  vec4 img = texture2D(u_tex, uv);

  float n = fbm(uv * 4.5 + vec2(u_time * 0.3, -u_time * 0.48));
  float breathe = 0.78 + 0.22 * sin(u_time * 1.1 + n * 7.0);
  float burn = min(edge * breathe * 0.85 + mouseBoost * 0.45, 1.05);
  float d = n - (1.0 - burn);

  float hole = smoothstep(0.0, 0.07, d);
  float rim = smoothstep(-0.11, 0.0, d) * (1.0 - hole);
  float charr = smoothstep(-0.26, -0.08, d) * (1.0 - rim) * (1.0 - hole);

  float hot = smoothstep(-0.05, 0.0, d);
  vec3 ember = mix(vec3(1.0, 0.38, 0.08), vec3(1.0, 0.85, 0.35), hot);

  vec3 col = img.rgb;
  col = mix(col, col * vec3(0.32, 0.24, 0.22), charr * 0.75);
  col = mix(col, ember, rim);
  col += ember * rim * 0.6;

  float alpha = img.a * (1.0 - hole);

  float gate = smoothstep(0.12, 0.5, edge * breathe) + mouseBoost;
  for (int i = 0; i < 3; i++) {
    float fi = float(i);
    float scale = 13.0 + fi * 8.0;
    vec2 sp = v_uv * scale + vec2(-u_time * (0.8 + fi * 0.5), -u_time * (2.0 + fi * 1.1));
    vec2 cell = floor(sp);
    float sh = hash(cell + fi * 13.7);
    if (sh > 0.7) {
      vec2 pos = 0.2 + 0.6 * vec2(hash(cell + 3.1), hash(cell + 7.7));
      pos.x += sin(u_time * (2.0 + sh * 3.0) + sh * 20.0) * 0.08;
      vec2 delta = fract(sp) - pos;
      float angle = sh * 6.2831 + u_time * (1.2 + sh * 2.0);
      vec2 r = mat2(cos(angle), -sin(angle), sin(angle), cos(angle)) * delta;
      float body = smoothstep(0.17, 0.03, length(r * vec2(1.0, 2.6)));
      float life = fract(u_time * (0.35 + sh * 0.5) + sh * 11.0);
      float glow = smoothstep(0.0, 0.1, life) * (1.0 - smoothstep(0.5, 0.95, life));
      float flicker = 0.75 + 0.25 * sin(u_time * 11.0 + sh * 40.0);
      vec3 flakeCol = mix(vec3(1.0, 0.4, 0.07), vec3(1.0, 0.93, 0.55), glow * flicker);
      float lum = body * glow * flicker * min(gate, 1.2);
      col += flakeCol * lum;
      alpha = max(alpha, lum * 0.95);
    }
  }

  gl_FragColor = vec4(col, alpha);
}
`

function paintFallbackArt(size: number): HTMLCanvasElement | null {
  const canvas = document.createElement("canvas")
  canvas.width = size
  canvas.height = size
  const ctx = canvas.getContext("2d")
  if (!ctx) return null

  const styles = getComputedStyle(document.documentElement)
  const token = (name: string, fallback: string) =>
    styles.getPropertyValue(name).trim() || fallback

  const blob = (cx: number, cy: number, r: number, color: string) => {
    const gradient = ctx.createRadialGradient(cx, cy, 0, cx, cy, r)
    gradient.addColorStop(0, color)
    gradient.addColorStop(0.55, color)
    gradient.addColorStop(1, "transparent")
    ctx.fillStyle = gradient
    ctx.beginPath()
    ctx.arc(cx, cy, r, 0, Math.PI * 2)
    ctx.fill()
  }

  ctx.fillStyle = token("--muted", "#ebebeb")
  ctx.fillRect(0, 0, size, size)
  ctx.globalAlpha = 0.7
  blob(size * 0.125, size * 0.125, size * 0.42, token("--primary", "#3392ff"))
  blob(size * 0.83, size * 0.58, size * 0.38, "#9ae600")
  blob(size * 0.5, size * 0.95, size * 0.42, "#ff8904")
  ctx.globalAlpha = 1

  return canvas
}

export function PlanArtFlame({
  src,
  className,
}: {
  src?: string
  className?: string
}) {
  const canvasRef = React.useRef<HTMLCanvasElement>(null)
  const [failed, setFailed] = React.useState(false)

  React.useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) return
    const gl = canvas.getContext("webgl", {
      alpha: true,
      premultipliedAlpha: false,
    })
    if (!gl) {
      setFailed(true)
      return
    }

    const { width, height } = canvas.getBoundingClientRect()
    const dpr = window.devicePixelRatio || 1
    canvas.width = width * dpr
    canvas.height = height * dpr
    gl.viewport(0, 0, canvas.width, canvas.height)

    const compile = (type: number, source: string) => {
      const shader = gl.createShader(type)!
      gl.shaderSource(shader, source)
      gl.compileShader(shader)
      return shader
    }
    const program = gl.createProgram()!
    gl.attachShader(program, compile(gl.VERTEX_SHADER, VERT))
    gl.attachShader(program, compile(gl.FRAGMENT_SHADER, FRAG))
    gl.linkProgram(program)
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
      setFailed(true)
      return
    }
    gl.useProgram(program)

    const buffer = gl.createBuffer()
    gl.bindBuffer(gl.ARRAY_BUFFER, buffer)
    gl.bufferData(
      gl.ARRAY_BUFFER,
      new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]),
      gl.STATIC_DRAW
    )
    const aPos = gl.getAttribLocation(program, "a_pos")
    gl.enableVertexAttribArray(aPos)
    gl.vertexAttribPointer(aPos, 2, gl.FLOAT, false, 0, 0)

    const uTime = gl.getUniformLocation(program, "u_time")
    const uMouse = gl.getUniformLocation(program, "u_mouse")
    const uMouseStr = gl.getUniformLocation(program, "u_mouseStr")
    gl.uniform1i(gl.getUniformLocation(program, "u_tex"), 0)

    const target = { x: 0.5, y: 0.5, str: 0 }
    const eased = { x: 0.5, y: 0.5, str: 0 }
    const onPointerMove = (event: PointerEvent) => {
      const rect = canvas.getBoundingClientRect()
      const x = (event.clientX - rect.left) / rect.width
      const y = 1 - (event.clientY - rect.top) / rect.height
      const inside = x > -0.15 && x < 1.15 && y > -0.15 && y < 1.15
      if (inside) {
        target.x = x
        target.y = y
      }
      target.str = inside ? 1 : 0
    }
    window.addEventListener("pointermove", onPointerMove)

    const texture = gl.createTexture()
    gl.activeTexture(gl.TEXTURE0)
    gl.bindTexture(gl.TEXTURE_2D, texture)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR)
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR)

    gl.enable(gl.BLEND)
    gl.blendFunc(gl.SRC_ALPHA, gl.ONE_MINUS_SRC_ALPHA)

    let raf = 0
    let disposed = false
    const start = performance.now()
    const draw = (now: number) => {
      gl.uniform1f(uTime, (now - start) / 1000)
      eased.x += (target.x - eased.x) * 0.12
      eased.y += (target.y - eased.y) * 0.12
      eased.str += (target.str - eased.str) * 0.07
      gl.uniform2f(uMouse, eased.x, eased.y)
      gl.uniform1f(uMouseStr, eased.str)
      gl.clearColor(0, 0, 0, 0)
      gl.clear(gl.COLOR_BUFFER_BIT)
      gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4)
      raf = requestAnimationFrame(draw)
    }

    const upload = (source: TexImageSource) => {
      gl.pixelStorei(gl.UNPACK_FLIP_Y_WEBGL, true)
      gl.texImage2D(
        gl.TEXTURE_2D,
        0,
        gl.RGBA,
        gl.RGBA,
        gl.UNSIGNED_BYTE,
        source
      )
      raf = requestAnimationFrame(draw)
    }

    if (src) {
      const image = new Image()
      image.onload = () => {
        if (disposed) return
        upload(image)
      }
      image.onerror = () => setFailed(true)
      image.src = src
    } else {
      const art = paintFallbackArt(512)
      if (!art) {
        setFailed(true)
        return
      }
      upload(art)
    }

    return () => {
      disposed = true
      cancelAnimationFrame(raf)
      window.removeEventListener("pointermove", onPointerMove)
    }
  }, [src])

  if (failed) {
    return (
      <div
        aria-hidden
        className={cn("relative overflow-hidden bg-muted", className)}
      >
        <div className="absolute -start-[20%] -top-[20%] size-[70%] rounded-full bg-primary/40 blur-2xl" />
        <div className="absolute -end-[10%] top-[30%] size-[55%] rounded-full bg-chart-2/40 blur-2xl" />
        <div className="absolute bottom-[-20%] start-[30%] size-[60%] rounded-full bg-orange-400/40 blur-2xl" />
      </div>
    )
  }

  return (
    <canvas
      ref={canvasRef}
      aria-hidden
      className={cn("size-full", className)}
    />
  )
}

"use client"

import * as React from "react"
import {
  CheckCircle2Icon,
  DatabaseIcon,
  PaletteIcon,
  Settings2Icon,
  SettingsIcon,
  StoreIcon,
  UserRoundIcon,
  WalletIcon,
  WorkflowIcon,
  WrenchIcon,
  XIcon,
} from "lucide-react"

import {
  Dialog,
  DialogContent,
  DialogTitle,
} from "@/components/ui/dialog"
import { cn } from "@/lib/utils"

import { SettingsGeneral } from "./settings-general"
import { SettingsProfile } from "./settings-profile"
import { SettingsStorage } from "./settings-storage"
import { SettingsTools } from "./settings-tools"

export type SettingsPage = "general" | "profile" | "storage" | "tools"

export interface SettingsModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  defaultPage?: SettingsPage
  planArtSrc?: string
}

type NavItem = {
  label: string
  icon: React.ComponentType<{ className?: string }>
  page?: SettingsPage
}

const NAV_GROUPS: { label: string; items: NavItem[] }[] = [
  {
    label: "Settings",
    items: [
      { label: "General", icon: Settings2Icon, page: "general" },
      { label: "Profile", icon: UserRoundIcon, page: "profile" },
      { label: "Appearance", icon: PaletteIcon },
      { label: "Billing", icon: WalletIcon },
      { label: "Rules", icon: WorkflowIcon },
      { label: "Tools", icon: WrenchIcon, page: "tools" },
      { label: "Storage", icon: DatabaseIcon, page: "storage" },
      { label: "Marketplace", icon: StoreIcon },
    ],
  },
  {
    label: "Desktop",
    items: [{ label: "General", icon: SettingsIcon }],
  },
]

const PAGE_TITLES: Record<SettingsPage, string> = {
  general: "General",
  profile: "Profile",
  storage: "Storage",
  tools: "Tools",
}

export function SettingsModal({
  open,
  onOpenChange,
  defaultPage = "general",
  planArtSrc,
}: SettingsModalProps) {
  const [page, setPage] = React.useState<SettingsPage>(defaultPage)
  const [savedPhase, setSavedPhase] = React.useState<
    "hidden" | "shown" | "leaving"
  >("hidden")
  const [contentScrolled, setContentScrolled] = React.useState(false)
  const scrollRef = React.useRef<HTMLDivElement>(null)
  const savedTimer = React.useRef<ReturnType<typeof setTimeout> | null>(null)

  React.useEffect(() => {
    if (!open) return
    setPage(defaultPage)
    setContentScrolled(false)
    scrollRef.current?.scrollTo({ top: 0 })
  }, [open, defaultPage])

  const showSavedToast = React.useCallback(() => {
    if (savedTimer.current) clearTimeout(savedTimer.current)
    setSavedPhase("shown")
    savedTimer.current = setTimeout(() => {
      setSavedPhase("leaving")
      savedTimer.current = setTimeout(() => setSavedPhase("hidden"), 220)
    }, 1800)
  }, [])

  React.useEffect(
    () => () => {
      if (savedTimer.current) clearTimeout(savedTimer.current)
    },
    []
  )

  const goTo = (next: SettingsPage) => {
    setPage(next)
    setContentScrolled(false)
    scrollRef.current?.scrollTo({ top: 0 })
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent
        showCloseButton={false}
        className={cn(
          "flex h-[min(614px,calc(100dvh-2rem))] w-full gap-0 overflow-clip border-border/70 bg-card p-0 shadow-soft",
          "rounded-[12px] sm:rounded-[12px]"
        )}
        style={{ maxWidth: "min(54rem, calc(100vw - 2rem))" }}
      >
        <DialogTitle className="sr-only">Settings</DialogTitle>

        <nav
          aria-label="Settings sections"
          className="flex w-14 shrink-0 flex-col gap-5 overflow-y-auto border-e border-border/70 bg-muted/30 p-2 sm:w-52 lg:w-56 dark:bg-muted/20"
        >
          {NAV_GROUPS.map((group) => (
            <div key={group.label} className="flex flex-col gap-0.5">
              <p className="mb-1 hidden px-2.5 text-[11px] font-medium tracking-[0.06em] text-muted-foreground uppercase sm:block">
                {group.label}
              </p>
              {group.items.map((item) => {
                const selected = item.page !== undefined && item.page === page
                const Icon = item.icon
                const available = Boolean(item.page)
                return (
                  <button
                    key={`${group.label}:${item.label}`}
                    type="button"
                    title={item.label}
                    aria-label={item.label}
                    aria-current={selected ? "page" : undefined}
                    disabled={!available}
                    onClick={() => {
                      if (!item.page) return
                      goTo(item.page)
                    }}
                    className={cn(
                      "group flex w-full items-center gap-2.5 rounded-[10px] px-2 py-2 text-start outline-none transition-colors",
                      "focus-visible:ring-2 focus-visible:ring-ring",
                      available
                        ? "cursor-pointer"
                        : "cursor-default opacity-45",
                      selected
                        ? "bg-card text-foreground shadow-xs ring-1 ring-border/60"
                        : available
                          ? "text-muted-foreground hover:bg-card/70 hover:text-foreground"
                          : "text-muted-foreground"
                    )}
                  >
                    <Icon
                      className={cn(
                        "size-[18px] shrink-0 transition-colors",
                        selected
                          ? "text-foreground"
                          : "text-muted-foreground group-hover:text-foreground"
                      )}
                      aria-hidden
                    />
                    <span className="hidden min-w-0 flex-1 truncate text-sm font-medium sm:block">
                      {item.label}
                    </span>
                    {!available ? (
                      <span className="ms-auto hidden rounded-full bg-muted px-1.5 py-0.5 text-[10px] font-medium tracking-wide text-muted-foreground uppercase sm:inline">
                        Soon
                      </span>
                    ) : null}
                  </button>
                )
              })}
            </div>
          ))}
        </nav>

        <div className="relative flex min-w-0 flex-1 flex-col bg-card">
          <div className="relative z-10 flex shrink-0 items-center justify-between gap-3 bg-card/95 px-5 pt-5 pb-3 backdrop-blur-sm sm:px-7 sm:pt-6">
            <h2 className="text-[17px] font-semibold tracking-tight text-foreground">
              {PAGE_TITLES[page]}
            </h2>
            <button
              type="button"
              aria-label="Close settings"
              onClick={() => onOpenChange(false)}
              className="flex size-7 cursor-pointer items-center justify-center rounded-full bg-muted text-muted-foreground transition-colors outline-none hover:bg-muted/80 hover:text-foreground focus-visible:ring-2 focus-visible:ring-ring"
            >
              <XIcon className="size-3.5" />
            </button>
          </div>

          <div
            ref={scrollRef}
            className="scrollbar-soft min-h-0 flex-1 overflow-y-auto px-5 pb-8 sm:px-7"
            onScroll={(e) =>
              setContentScrolled(e.currentTarget.scrollTop > 2)
            }
          >
            <div
              key={page}
              className="animate-in fade-in-0 slide-in-from-bottom-1 duration-200"
            >
              {page === "profile" ? (
                <SettingsProfile onSaved={showSavedToast} />
              ) : page === "storage" ? (
                <SettingsStorage />
              ) : page === "tools" ? (
                <SettingsTools />
              ) : (
                <SettingsGeneral planArtSrc={planArtSrc} />
              )}
            </div>
          </div>

          <div
            aria-hidden
            className={cn(
              "pointer-events-none absolute inset-x-0 top-[3.25rem] h-8 bg-gradient-to-b from-card to-transparent transition-opacity duration-200",
              contentScrolled ? "opacity-100" : "opacity-0"
            )}
          />
        </div>

        <div
          aria-live="polite"
          className={cn(
            "pointer-events-none absolute bottom-0 left-1/2 z-20 flex -translate-x-1/2 items-center gap-1.5",
            "rounded-full border border-border/70 bg-card py-1.5 pe-3 ps-2 shadow-soft",
            "transition-[opacity,transform,filter] duration-200 ease-out",
            savedPhase === "shown" &&
              "translate-y-1/2 scale-100 opacity-100 blur-0",
            savedPhase === "hidden" &&
              "translate-y-[calc(50%+14px)] scale-90 opacity-0 blur-[2px]",
            savedPhase === "leaving" &&
              "translate-y-[calc(50%-8px)] scale-95 opacity-0 blur-[1px]"
          )}
        >
          <CheckCircle2Icon className="size-4 text-emerald-500" aria-hidden />
          <span className="text-xs font-medium text-foreground">Saved</span>
        </div>
      </DialogContent>
    </Dialog>
  )
}

"use client"

import * as React from "react"
import { LogOutIcon, MailIcon } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Switch } from "@/components/ui/switch"
import { cn } from "@/lib/utils"

import { SettingsCard, SettingsRow } from "./settings-rows"

const fieldClass =
  "h-8 w-[202px] shrink-0 border-border/70 bg-card text-sm shadow-xs"

export function SettingsProfile({ onSaved }: { onSaved?: () => void } = {}) {
  const [email, setEmail] = React.useState("hi@sonojs.dev")
  const [firstName, setFirstName] = React.useState("Alex")
  const [lastName, setLastName] = React.useState("Rivera")
  const [publicProfile, setPublicProfile] = React.useState(true)
  const committed = React.useRef({ email, firstName, lastName })

  const commit = (key: "email" | "firstName" | "lastName", value: string) => {
    if (committed.current[key] === value) return
    committed.current[key] = value
    onSaved?.()
  }

  return (
    <div className="flex flex-col gap-6">
      <SettingsCard>
        <SettingsRow label="Email">
          <div className="relative w-[202px] shrink-0">
            <MailIcon className="pointer-events-none absolute start-2.5 top-1/2 size-3.5 -translate-y-1/2 text-muted-foreground" />
            <Input
              type="email"
              aria-label="Email"
              dir="ltr"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              onBlur={() => commit("email", email)}
              onKeyDown={(e) => {
                if (e.key === "Enter") (e.target as HTMLElement).blur()
              }}
              className={cn(fieldClass, "ps-8")}
            />
          </div>
        </SettingsRow>
        <SettingsRow label="First name">
          <Input
            aria-label="First name"
            value={firstName}
            onChange={(e) => setFirstName(e.target.value)}
            onBlur={() => commit("firstName", firstName)}
            onKeyDown={(e) => {
              if (e.key === "Enter") (e.target as HTMLElement).blur()
            }}
            className={fieldClass}
          />
        </SettingsRow>
        <SettingsRow label="Last name">
          <Input
            aria-label="Last name"
            value={lastName}
            onChange={(e) => setLastName(e.target.value)}
            onBlur={() => commit("lastName", lastName)}
            onKeyDown={(e) => {
              if (e.key === "Enter") (e.target as HTMLElement).blur()
            }}
            className={fieldClass}
          />
        </SettingsRow>
      </SettingsCard>

      <SettingsCard>
        <SettingsRow
          label="SonoJS account"
          description="Manage billing and seat access"
        >
          <Button variant="outline" size="sm" className="h-8 shadow-xs">
            Manage
          </Button>
        </SettingsRow>
        <SettingsRow
          label="Public profile"
          description="When enabled your profile page is visible to anyone"
        >
          <Switch
            checked={publicProfile}
            onCheckedChange={setPublicProfile}
            aria-label="Public profile"
          />
        </SettingsRow>
        <SettingsRow label="Device ID">
          <span
            dir="ltr"
